/*
 * [算法說明]
 * 本題要求將螺旋狀編號的蜂巢 (Willi) 轉換為坐標系統 (Maja)。
 * 蜂巢是六邊形的，編號從中心 1 開始，按順時針螺旋向外擴展。
 * 我們可以觀察到螺旋的規律，並預先計算出前 100,000 個編號的坐標。
 * 
 * 螺旋路徑可以分為不同的「層」(Radius i)：
 * - 層 0：只有編號 1，坐標 (0, 0)。
 * - 層 i (i >= 1) 的移動規律：
 *   1. 向上移動到 (x, y+1) [起始點]
 *   2. 向左下移動 i-1 步 (dx=-1, dy=1)
 *   3. 向左移動 i 步 (dx=-1, dy=0)
 *   4. 向左上移動 i 步 (dx=0, dy=-1)
 *   5. 向右上移動 i 步 (dx=1, dy=-1)
 *   6. 向右移動 i 步 (dx=1, dy=0)
 *   7. 向右下移動 i 步 (dx=0, dy=1)
 * 
 * 預先存儲坐標後，對於每個輸入編號直接輸出即可。
 */

#include <iostream>
#include <vector>

using namespace std;

struct Point {
    int x, y;
};

Point result[100001];

void precompute() {
    result[1] = {0, 0};
    int curr = 2;
    int x = 0, y = 0;
    int i = 1;
    while (curr <= 100000) {
        // 1. Move (0, 1) once to start the layer
        y++;
        if (curr <= 100000) result[curr++] = {x, y};

        // 2. Move (-1, 1) i-1 times
        for (int k = 0; k < i - 1 && curr <= 100000; k++) {
            x--; y++;
            result[curr++] = {x, y};
        }

        // 3. Move (-1, 0) i times
        for (int k = 0; k < i && curr <= 100000; k++) {
            x--;
            result[curr++] = {x, y};
        }

        // 4. Move (0, -1) i times
        for (int k = 0; k < i && curr <= 100000; k++) {
            y--;
            result[curr++] = {x, y};
        }

        // 5. Move (1, -1) i times
        for (int k = 0; k < i && curr <= 100000; k++) {
            x++; y--;
            result[curr++] = {x, y};
        }

        // 6. Move (1, 0) i times
        for (int k = 0; k < i && curr <= 100000; k++) {
            x++;
            result[curr++] = {x, y};
        }

        // 7. Move (0, 1) i times
        // Note: The last move of this sequence actually completes the layer and stays at the position 
        // just before the next layer's start.
        for (int k = 0; k < i && curr <= 100000; k++) {
            y++;
            if (curr <= 100000) result[curr++] = {x, y};
        }

        i++;
    }
}

int main() {
    precompute();
    int n;
    while (cin >> n) {
        cout << result[n].x << " " << result[n].y << endl;
    }
    return 0;
}
